"""Paged technical field inventory with safe local rendering, no additional requests."""
import json
from html import escape
from contextual_help import tip,STYLE as HELP_STYLE

LIMITS='Inventário combinado dos campos retornados pela ficha técnica e pela API de atributos da categoria. A fonte aparece em cada campo; não certifica todos os campos existentes no Mercado Livre. Oculto é uma marca oficial da API e não confirma permissão de edição ou aplicabilidade ao produto. Sem marca required significa complementar nesta resposta, não dispensa regras de publicação ou condições. Valor identificado não valida o conteúdo. Ausência por variação pode ter informação no anúncio principal; não confirma erro. Não aplicável, valores compostos e respostas inválidas ficam não verificáveis. Campos gerenciados não pedem edição direta.'
LABELS={'publication':'Obrigatório na regra de publicação consultada','conditional':'Obrigatório na consulta condicional do Mercado Livre','context':'Condição de publicação a conferir','unknown':'Regra de publicação não verificada'}
SOURCES={'sheet':'Ficha técnica','category':'API da categoria','both':'Ficha técnica + API da categoria'}
HIDDEN={'hidden':'Oculto na API','new_hidden':'Oculto para novos','used_hidden':'Oculto para usados'}
NAMES={'i':'Valor identificado','r':'Sem valor identificado','u':'Não verificável'}


def display(row):
    rule=LABELS.get(row['publication'],'Exigido na ficha · não confirma impedimento de publicação' if row['required'] else 'Complementar nesta ficha · sem exigência confirmada' if row.get('source')!='category' else 'Sem exigência confirmada na API consultada')
    action='Campo gerenciado pelo Mercado Livre' if row['managed'] else ('Conferir preenchimento e aplicabilidade' if row['required'] or row['publication'] in ('publication','conditional','context','unknown') else 'Avaliar oportunidade de preenchimento') if row['state']=='review' else ''
    return dict(source=row.get('source','sheet'),managed=row['managed'],hidden=[HIDDEN[t] for t in row.get('hidden_tags',[])],name=row['name'],code=row['id'],state=row['state'],required=row['required'],rule=rule,message=row['message'],action=action,variants=row['variation_states'])


def card(row,ids,total):
    esc=lambda value:escape(str(value),quote=True)
    out='<article class="cs-tech-row" data-presence="'+row['state']+'"><h5>'+esc(row['name'])+'</h5><small>'+esc(row['code'])+'</small><p>'+esc(row['rule'])+'</p><strong>'+esc(row['message'])+'</strong>'
    out+='<div class="cs-tech-meta"><span>'+SOURCES[row['source']]+'</span>'+''.join('<span>'+label+'</span>' for label in row['hidden'])+'</div>'
    if row['action']:out+='<p>'+esc(row['action'])+'</p>'
    if row['variants']:
        out+='<details><summary>Conferir variações</summary><ul>'
        for identifier,state in zip(ids,row['variants']):out+='<li>Variação '+esc(identifier)+': '+NAMES[state]+'</li>'
        out+='</ul>'+('<p>Exibidas 100 de '+str(total)+' variações.</p>' if total>100 else '')+'</details>'
    elif row['variants'] is None:out+='<p>Variações não verificáveis.</p>'
    return out+'</article>'


def render(result):
    out='<section class="cs-technical" data-inventory><h4 tabindex="-1">Ficha técnica da categoria'+tip('Ficha técnica',LIMITS)+'</h4>'
    if result.get('state')!='read':return out+'<p>Ficha técnica não verificada. '+escape(result.get('message','Consulta indisponível.'))+'</p></section>'+HELP_STYLE
    rows=[display(row) for row in result['rows']];counts={key:sum(r['state']==key for r in rows) for key in ('informed','review','unknown')}
    required=sum(r['required'] for r in rows);sheet=sum(r['source']!='category' for r in rows);api=len(rows)-sheet;hidden=sum(bool(r['hidden']) for r in rows)
    out+='<div class="cs-tech-counts"><span>'+str(len(rows))+' campos retornados</span><span>'+str(required)+' exigidos na ficha</span><span>'+str(sheet-required)+' complementares na ficha</span><span>'+str(api)+' somente na API</span><span>'+str(hidden)+' ocultos</span><span>'+str(counts['informed'])+' com valor</span><span>'+str(counts['review'])+' para conferir</span><span>'+str(counts['unknown'])+' não verificáveis</span></div>'
    if result.get('incomplete_flag') is True:out+='<p>O Mercado Livre retornou o sinal de ficha técnica incompleta nesta leitura.</p>'
    if not rows:return out+'<p>Nenhum campo retornado nesta ficha.</p></section>'+HELP_STYLE
    out+='<div class="cs-tech-controls"><label>Campo<input type="search" class="cs-tech-search" placeholder="Nome ou identificador"></label><label>Grupo<select class="cs-tech-group"><option value="all">Todos</option><option value="required">Exigidos na ficha</option><option value="extra">Complementares na ficha</option><option value="api">Somente na API</option><option value="hidden">Ocultos na API</option><option value="managed">Gerenciados pelo ML</option></select></label><label>Preenchimento<select class="cs-tech-state"><option value="all">Todos</option><option value="review">Para conferir</option><option value="informed">Com valor</option><option value="unknown">Não verificáveis</option></select></label></div>'
    out+='<div class="cs-tech-list">'+''.join(card(row,result['variation_ids'],result['variation_count']) for row in rows[:50])+'</div><div class="cs-tech-pages"><button type="button" data-prev disabled>Anterior</button><output aria-live="polite">1–'+str(min(50,len(rows)))+' de '+str(len(rows))+'</output><button type="button" data-next'+(' disabled' if len(rows)<=50 else '')+'>Próxima</button></div><noscript>Exibidos os primeiros 50 campos. Ative JavaScript para navegar pelos demais campos e usar os filtros.</noscript>'
    data=json.dumps(dict(rows=rows,ids=result['variation_ids'],total=result['variation_count']),ensure_ascii=False).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
    out+='<script type="application/json" class="cs-tech-data">'+data+'</script></section>'
    return out+HELP_STYLE+STYLE+SCRIPT

STYLE='''<style>.cs-tech-counts{display:flex;flex-wrap:wrap;gap:8px;margin:14px 0}.cs-tech-counts span{border:1px solid #426184;border-radius:8px;padding:8px 10px;font-size:12px}.cs-tech-controls{display:grid;grid-template-columns:2fr 1fr 1fr;gap:12px}.cs-tech-controls label{min-width:0}.cs-tech-controls :is(input,select){display:block;width:100%;box-sizing:border-box;min-width:0;margin-top:6px}.cs-tech-row{border:1px solid #426184;border-radius:10px;padding:14px;margin:12px 0;overflow-wrap:anywhere}.cs-tech-row[data-presence=review]{border-left:4px solid #c08d54}.cs-tech-meta{display:flex;flex-wrap:wrap;gap:6px;margin-top:10px}.cs-tech-meta span{border:1px solid #426184;border-radius:6px;padding:4px 7px;font-size:11px}.cs-tech-row h5{font:inherit;font-weight:700;margin:0 0 8px}.cs-technical summary{cursor:pointer;margin:12px 0}.cs-tech-pages{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.cs-tech-pages button:disabled{opacity:.5;cursor:default}.cs-technical h4:focus{outline:none}@media(max-width:600px){.cs-tech-controls{grid-template-columns:1fr}}</style>'''
SCRIPT='''<script>document.querySelectorAll('.cs-technical[data-inventory]').forEach(root=>{if(root.dataset.bound)return;const raw=root.querySelector('.cs-tech-data');if(!raw)return;root.dataset.bound='1';const data=JSON.parse(raw.textContent),list=root.querySelector('.cs-tech-list'),search=root.querySelector('.cs-tech-search'),group=root.querySelector('.cs-tech-group'),state=root.querySelector('.cs-tech-state'),prev=root.querySelector('[data-prev]'),next=root.querySelector('[data-next]'),output=root.querySelector('output');let page=0;const names={i:'Valor identificado',r:'Sem valor identificado',u:'Não verificável'};function node(tag,text,parent){const el=document.createElement(tag);el.textContent=text;parent.appendChild(el);return el}function draw(){const query=search.value.trim().toLocaleLowerCase('pt-BR');const rows=data.rows.filter(r=>(group.value==='all'||group.value==='required'&&r.required||group.value==='extra'&&!r.required&&r.source!=='category'||group.value==='api'&&r.source==='category'||group.value==='hidden'&&r.hidden.length||group.value==='managed'&&r.managed)&&(state.value==='all'||r.state===state.value)&&(!query||(r.name+' '+r.code).toLocaleLowerCase('pt-BR').includes(query)));page=Math.min(page,Math.max(0,Math.ceil(rows.length/50)-1));list.textContent='';for(const row of rows.slice(page*50,(page+1)*50)){const card=node('article','',list);card.className='cs-tech-row';card.dataset.presence=row.state;node('h5',row.name,card);node('small',row.code,card);node('p',row.rule,card);node('strong',row.message,card);const meta=node('div','',card);meta.className='cs-tech-meta';node('span',({sheet:'Ficha técnica',category:'API da categoria',both:'Ficha técnica + API da categoria'})[row.source],meta);for(const label of row.hidden)node('span',label,meta);if(row.action)node('p',row.action,card);if(row.variants){const details=node('details','',card);node('summary','Conferir variações',details);const ul=node('ul','',details);Array.from(row.variants).forEach((s,i)=>node('li','Variação '+data.ids[i]+': '+names[s],ul));if(data.total>100)node('p','Exibidas 100 de '+data.total+' variações.',details)}else if(row.variants===null)node('p','Variações não verificáveis.',card)}if(!rows.length)node('p','Nenhum campo neste filtro.',list);output.textContent=(rows.length?page*50+1:0)+'–'+Math.min((page+1)*50,rows.length)+' de '+rows.length;prev.disabled=page===0;next.disabled=(page+1)*50>=rows.length}for(const el of [group,state])el.addEventListener('change',()=>{page=0;draw()});search.addEventListener('input',()=>{page=0;draw()});prev.addEventListener('click',()=>{page--;draw();root.querySelector('h4').focus()});next.addEventListener('click',()=>{page++;draw();root.querySelector('h4').focus()});draw()});</script>'''
